  Q("poh", "On an airspeed indicator, the red line marks:", ["VNE", "VNO", "VFE", "VA"], 0, "Red line = never exceed speed."),

  Q("low-flying", "Except when taking off or landing, an aircraft over a congested area must not fly below:", ["1,000 ft above the highest obstacle within 600 m", "500 ft above the highest obstacle within 150 m", "1,500 ft above the highest obstacle within 600 m", "1,000 ft above the highest obstacle within 150 m"], 0, "SERA.5005(f)(1): 1,000 ft / 600 m. Note the mixed units."),
  Q("low-flying", "In the UK, outside congested areas, an aircraft must not fly closer than 500 ft to any:", ["person, vessel, vehicle or structure", "building", "aerodrome", "controlled airspace boundary"], 0, "The UK applies a 500 ft distance rule instead of the SERA 500 ft height rule."),
  Q("low-flying", "Over a congested area, as well as the 1,000 ft rule, the aircraft must be high enough to:", ["land clear without undue hazard if the engine fails", "remain above any cloud over the built-up area", "remain in radio contact with the nearest ATSU", "be seen on radar by the nearest ATC unit"], 0, "You must be able to glide clear of the built-up area."),
  Q("low-flying", "The low flying minima do not apply when:", ["taking off or landing", "flying a single-engine aircraft", "flying below cloud", "flying at weekends"], 0, "Take-off and landing in accordance with normal aviation practice are excepted."),
  Q("low-flying", "For a VFR flight at night, the minimum height is 1,000 ft above the highest obstacle within:", ["8 km", "5 km", "600 m", "150 m"], 0, "Night VFR: 1,000 ft / 8 km."),
  Q("low-flying", "You are flying over open countryside at 400 ft AGL. A tractor is 300 ft from your aircraft. Under UK rules, this is:", ["illegal, because you are within 500 ft of a vehicle", "legal, because you are above 300 ft", "legal, because the rule only applies to buildings", "legal, because open countryside has no minimum"], 0, "The 500 ft rule applies to persons, vessels, vehicles and structures."),
  Q("low-flying", "The congested area rule uses a horizontal radius of:", ["600 metres", "600 feet", "150 metres", "1,000 metres"], 0, "1,000 FEET above the highest obstacle within 600 METRES."),

  Q("collision-avoidance", "Who has ultimate responsibility for avoiding a collision? The:", ["pilot-in-command", "air traffic controller", "aircraft with right of way", "aircraft on the left"], 0, "The PIC is never relieved of this responsibility."),
  Q("collision-avoidance", "Vigilance for the purpose of detecting potential collisions must be maintained:", ["regardless of the type of flight or class of airspace", "only in Class G airspace", "only in VMC", "only when not receiving a radar service"], 0, "SERA.3210(a)."),
  Q("collision-avoidance", "Another aircraft stays in the same position on your windscreen but grows larger. This indicates:", ["a collision course", "that it is moving away", "that it will pass behind you", "that it is overtaking you"], 0, "Constant relative bearing + decreasing range = collision course."),
  Q("collision-avoidance", "An effective lookout scan uses sectors of about:", ["10–15 degrees, pausing about 1 second in each", "45 degrees, pausing about 5 seconds in each", "90 degrees, sweeping continuously", "360 degrees, once every 10 minutes"], 0, "Short pauses let your eyes focus and detect movement."),
  Q("collision-avoidance", "You are VFR with an ATC clearance in Class D airspace. Who is responsible for avoiding other VFR traffic?", ["You, the pilot-in-command", "ATC", "The aircraft with the higher priority", "The aerodrome operator"], 0, "ATC don't separate VFR from VFR in Class D; they pass traffic information."),
  Q("collision-avoidance", "An aircraft fitted with ACAS receives a resolution advisory that conflicts with an ATC instruction. The pilot should:", ["follow the resolution advisory", "follow the ATC instruction", "ignore both and maintain course", "ask ATC which to follow"], 0, "Follow the RA, then tell ATC."),

  Q("crs", "After maintenance, an aircraft may not fly until a:", ["Certificate of Release to Service has been issued", "new C of A has been issued", "CAA inspection has been completed", "new weight schedule has been issued"], 0, "A CRS is needed after maintenance."),
  Q("crs", "A Certificate of Release to Service certifies that:", ["the maintenance was carried out correctly and the aircraft is fit for release", "the aircraft is insured for the flight and the pilot is named on the policy", "the pilot is medically fit and current to fly the aircraft", "the aircraft has passed its airworthiness review for the next 12 months"], 0, "It certifies the work and the release to service."),
  Q("crs", "Who may issue a Certificate of Release to Service?", ["Authorised certifying staff or an approved maintenance organisation", "Any licensed pilot who has flown the aircraft in the last 90 days", "The aircraft's insurer, after inspecting the work", "The CAA, after an inspection of the aircraft"], 0, "Only authorised persons or organisations (or a pilot-owner for permitted tasks)."),
  Q("crs", "Under Part-ML, a pilot-owner may issue a CRS for:", ["permitted pilot-owner maintenance tasks only", "any maintenance they carry out", "the annual inspection", "modifications to the aircraft"], 0, "Pilot-owners are limited to the defined pilot-owner tasks."),
  Q("crs", "The last maintenance entry in the tech log has no CRS signature. What should the pilot do?", ["Not fly until a CRS is issued", "Fly if the work looks complete", "Sign the CRS themselves", "Fly locally only"], 0, "No CRS = not released to service."),

  Q("preflight-docs", "Before flight, who must be satisfied that the aircraft is airworthy and its documents are valid? The:", ["pilot-in-command", "aircraft owner", "flying club secretary", "air traffic controller"], 0, "A PIC responsibility."),
  Q("preflight-docs", "The tech log shows 1247.3 hours. The next 50-hour check is due at 1248.0 hours. Your planned flight is 1.5 hours. What should you do?", ["Not fly as planned", "Fly, because the check isn't due yet", "Fly and report it afterwards", "Fly in the circuit only"], 0, "1247.3 + 1.5 = 1248.8 h, past the 1248.0 h limit."),
  Q("preflight-docs", "The aircraft's ARC expired yesterday. The aircraft:", ["must not fly until the ARC is renewed", "may fly for up to 30 days", "may fly locally only", "may fly if the C of A is in date"], 0, "The C of A is only valid with a current ARC."),
  Q("preflight-docs", "Where would you look to see whether a previous pilot reported a defect?", ["The technical log", "The POH", "The weight schedule", "The Certificate of Registration"], 0, "Defects are recorded in the tech log."),
  Q("preflight-docs", "Which of these would make an aircraft a 'no-go' before flight?", ["An unrectified defect affecting airworthiness", "A torn seat cover in the rear cabin", "A paint chip on the propeller spinner", "A missing receipt for the last fuel uplift"], 0, "Airworthiness defects must be fixed or properly deferred."),

  Q("landing-right-of-way", "Two powered aeroplanes are approaching to land. Which has the right of way? The:", ["lower one", "higher one", "faster one", "one on the right"], 0, "The higher aircraft gives way to the lower."),
  Q("landing-right-of-way", "The lower of two aircraft approaching to land must not:", ["cut in front of or overtake an aircraft on final", "land before the higher aircraft has turned base", "use the full length of the runway", "request a landing clearance from ATC"], 0, "Priority doesn't allow cutting in."),
  Q("landing-right-of-way", "A powered aeroplane and a glider are both approaching to land. The glider is higher. Which gives way? The:", ["powered aeroplane", "glider", "aircraft on the left", "aircraft that is lower"], 0, "Power-driven aircraft give way to gliders, regardless of height."),
  Q("landing-right-of-way", "An aircraft in flight or on the ground must give way to aircraft:", ["landing or in the final stages of an approach", "on the downwind leg of the circuit", "holding at the runway-holding position", "taxiing towards the apron after landing"], 0, "Landing aircraft have priority."),
  Q("landing-right-of-way", "You learn that another aircraft is compelled to land due to an engine problem. What should you do?", ["Give way to it", "Continue your approach if you are lower", "Land first to clear the runway", "Orbit overhead the runway"], 0, "Give way to an aircraft compelled to land."),
  Q("landing-right-of-way", "An aircraft taxiing on the manoeuvring area must give way to aircraft:", ["taking off or about to take off", "being towed by vehicles", "parked on the apron", "holding at the fuel pumps"], 0, "Taxiing aircraft give way to departing and landing aircraft."),

  Q("technical-log", "The main purpose of the aircraft technical log is to record:", ["flights, defects, rectifications and maintenance status", "the pilot's personal flying hours and ratings", "the aircraft's basic weight and centre of gravity", "the aircraft's ownership and registration history"], 0, "It's the aircraft's working record between scheduled maintenance."),
  Q("technical-log", "A defect discovered during a flight should be:", ["entered in the technical log by the PIC after the flight", "reported only if it gets worse", "recorded in the pilot's personal log book", "reported to ATC only"], 0, "Record defects so they're dealt with before the next flight."),
  Q("technical-log", "Rectification of a defect in the technical log is certified by a:", ["Certificate of Release to Service", "signature from the next pilot to fly it", "new weight schedule for the aircraft", "new Airworthiness Review Certificate"], 0, "A CRS certifies the rectification."),
  Q("technical-log", "Before flight, the technical log should be checked for:", ["open defects and hours to the next check", "the previous pilot's licence number", "the weather forecast", "NOTAMs"], 0, "Defects and maintenance status."),

  Q("right-of-way-obligations", "An aircraft that has the right of way should:", ["maintain its heading and speed", "climb to show it has seen the other aircraft", "turn right", "reduce speed"], 0, "SERA.3210(b)."),
  Q("right-of-way-obligations", "An aircraft giving way should avoid passing:", ["over, under or in front of the other aircraft", "behind the other aircraft", "to the right of the other aircraft", "below 500 ft"], 0, "Unless well clear and allowing for wake turbulence — SERA.3210(a)."),
  Q("right-of-way-obligations", "The stand-on aircraft maintains its heading and speed so that:", ["its path is predictable to the give-way aircraft", "it uses less fuel than if it manoeuvred", "it stays on its planned flight-plan route", "ATC can keep tracking it on radar"], 0, "Predictability stops both aircraft manoeuvring into each other."),
  Q("right-of-way-obligations", "The stand-on aircraft sees that the give-way aircraft is not taking avoiding action. What should the stand-on aircraft do?", ["Take whatever action best avoids a collision", "Maintain heading and speed regardless", "Turn left", "Transmit a MAYDAY"], 0, "The PIC is never relieved of collision avoidance responsibility."),
  Q("right-of-way-obligations", "When giving way, the pilot should allow for the effect of:", ["wake turbulence", "the other aircraft's registration", "the time of day", "the other aircraft's fuel state"], 0, "Pass well clear, allowing for wake turbulence."),

  Q("signal-area", "What does a horizontal red square with one yellow diagonal in the signals area indicate?", ["Take special care when landing, as the manoeuvring area is in poor condition", "Landing is prohibited, and the prohibition is likely to continue", "Glider flying is in progress", "Ground movement is confined to hard surfaces"], 0, "One diagonal = take care. Two diagonals (a cross) = landing prohibited."),
  Q("signal-area", "What does a horizontal red square with yellow diagonals forming a cross indicate?", ["Landing is prohibited, and the prohibition is likely to continue", "Take special care when landing, as the manoeuvring area is in poor condition", "A right-hand circuit is in force", "Helicopters must land in the designated area"], 0, "The cross crosses out the aerodrome."),
  Q("signal-area", "What does a horizontal white dumb-bell in the signals area indicate?", ["Aircraft must land, take off and taxi on hard surfaces only", "Aircraft must land and take off on runways only, but may taxi on grass", "Glider flying is in progress", "Light aircraft may use the grass area"], 0, "Plain dumb-bell = ALL ground movement on hard surfaces."),
  Q("signal-area", "What does a white dumb-bell with a black stripe across each disc indicate?", ["Aircraft must land and take off on runways only, but may taxi on grass", "Aircraft must land, take off and taxi on hard surfaces only", "The aerodrome is closed", "Glider launching is in progress"], 0, "The stripes relax the rule: only take-off and landing must be on runways."),
  Q("signal-area", "What does a white double cross in the signals area indicate?", ["Glider flying is in progress", "Landing is prohibited", "A right-hand circuit is in force", "Helicopters must land in the designated area"], 0, "Double cross (ground) = two red balls (mast) = gliding."),
  Q("signal-area", "When a white landing T is displayed, you should land:", ["parallel to the shaft, towards the cross-arm", "parallel to the cross-arm", "parallel to the shaft, away from the cross-arm", "in any direction into wind"], 0, "Land along the shaft, heading towards the cross-arm."),
  Q("signal-area", "What does a square sign showing a black C on a yellow background indicate?", ["The pilot reporting point", "Customs reporting", "Class C airspace", "The aerodrome is closed"], 0, "C marks where pilots report to the ATS unit — not customs, not Class C."),
  Q("signal-area", "What does a red and yellow chequered flag or board indicate?", ["Aircraft may move on the manoeuvring area only with ATC permission", "The aerodrome is closed to all aircraft until further notice", "Customs clearance is required before aircraft may move", "The aerodrome fire and rescue service is available"], 0, "Chequered board = ATC permission needed to move."),
  Q("signal-area", "What does a red and yellow striped arrow bent through 90° in the signals area indicate?", ["A right-hand circuit is in force", "A left-hand circuit is in force", "The runway is closed", "Glider winching is in progress"], 0, "Left-hand circuits are the default, so only right-hand ones are signalled."),
  Q("signal-area", "What does a black ball suspended from a mast indicate?", ["Take-off and landing directions are not necessarily the same", "Glider flying is in progress at the aerodrome", "The aerodrome is closed to all traffic", "A right-hand circuit is in force for all runways"], 0, "Black ball (mast) = white disc next to the T (ground)."),
  Q("signal-area", "What does a white letter H in the signals area indicate?", ["Helicopters must take off and land only within the designated area", "There is a hospital helipad near the aerodrome", "Aircraft must hold position until cleared by ATC", "Heavy aircraft are operating, so expect wake turbulence"], 0, "H = helicopter area."),
  Q("signal-area", "Which mast signal indicates that glider flying is in progress?", ["Two red balls", "A black ball", "A rectangular green flag", "A red and yellow chequered flag"], 0, "Two red balls = gliding."),
  Q("signal-area", "Which mast signal indicates that a right-hand circuit is in force?", ["A rectangular green flag", "Two red balls", "A black ball", "A red and yellow chequered flag"], 0, "Green flag = right-hand circuit."),
  Q("signal-area", "Where is the signals area normally located?", ["Near the control tower, visible from the air", "At the threshold of the main runway", "Beyond the end of the stopway", "On the apron next to the fuel pumps"], 0, "It is designed to be read from overhead."),

  Q("notification-of-arrival", "You filed a flight plan but divert to a different aerodrome. Within how long of your ETA at the original destination must you inform ATS?", ["30 minutes", "15 minutes", "1 hour", "2 hours"], 0, "After 30 minutes past ETA, overdue action may begin."),
  Q("notification-of-arrival", "You land at an aerodrome with no ATS unit after a flight with a filed flight plan. How should the arrival report be made?", ["By the quickest means to the nearest ATS unit", "By post to the departure ATS unit within 7 days", "Only if the nearest ATS unit requests it", "In person to the aerodrome owner only"], 0, "SERA.4020."),
  Q("notification-of-arrival", "Who is responsible for closing a flight plan? The:", ["pilot-in-command", "departure ATSU", "aircraft owner", "destination aerodrome operator"], 0, "It's the PIC's responsibility."),
  Q("notification-of-arrival", "'Booking out' means informing the ATSU of your:", ["intended departure and flight details", "landing fee payment and fuel uplift", "aircraft defects and maintenance status", "radio frequency and transponder code"], 0, "Booking out = departure; booking in = arrival."),
  Q("notification-of-arrival", "An aerodrome shown as PPR requires:", ["prior permission before arrival", "prior payment before arrival", "a professional pilot's licence", "permission from customs"], 0, "PPR = Prior Permission Required."),

  Q("aerodrome-lighting", "What colour are runway threshold lights?", ["Green", "Red", "White", "Blue"], 0, "Green to get in."),
  Q("aerodrome-lighting", "What colour are runway end lights, as seen from the runway?", ["Red", "Green", "White", "Yellow"], 0, "Red at the end."),
  Q("aerodrome-lighting", "What colour are taxiway edge lights?", ["Blue", "Green", "White", "Yellow"], 0, "Blue for boundaries."),
  Q("aerodrome-lighting", "What colour are taxiway centreline lights?", ["Green", "Blue", "White", "Red"], 0, "Green centreline, blue edges."),
  Q("aerodrome-lighting", "On a four-light PAPI, you see two white and two red lights. You are:", ["on the glide path", "slightly high", "slightly low", "well below the glide path"], 0, "2 white + 2 red = on slope."),
  Q("aerodrome-lighting", "On a four-light PAPI, you see four red lights. You are:", ["well below the glide path", "well above the glide path", "on the glide path", "slightly above the glide path"], 0, "All red = too low."),
  Q("aerodrome-lighting", "On a four-light PAPI, you see three white lights and one red light. You are:", ["slightly above the glide path", "slightly below the glide path", "on the glide path", "well below the glide path"], 0, "More white = higher."),
  Q("aerodrome-lighting", "An aerodrome identification beacon at a civil aerodrome flashes:", ["green Morse code", "red Morse code", "alternating white and green", "steady white"], 0, "Civil = green; military = red."),
  Q("aerodrome-lighting", "You reach a lit red stop bar and ATC has cleared you onto the runway. What should you do?", ["Hold and query ATC", "Proceed, as you have a clearance", "Cross slowly", "Flash your landing light and proceed"], 0, "Never cross a lit red stop bar."),
  Q("aerodrome-lighting", "What do pairs of alternately flashing yellow lights at a taxiway holding position indicate?", ["A runway ahead", "An obstacle", "The taxiway edge", "An apron entrance"], 0, "Runway guard lights."),
  Q("aerodrome-lighting", "What colour is the runway centreline lighting over the last 300 m of the runway?", ["Red", "White", "Alternating red and white", "Green"], 0, "Alternating red/white from 900 m to 300 m remaining, then red."),

  Q("light-signals", "What does a steady green light directed at an aircraft in flight mean?", ["Cleared to land", "Return for landing", "Cleared to taxi", "Give way to other aircraft and continue circling"], 0, "Steady green in the air = cleared to land."),
  Q("light-signals", "What does a steady red light directed at an aircraft in flight mean?", ["Give way to other aircraft and continue circling", "Aerodrome unsafe, do not land", "Land at this aerodrome and proceed to the apron", "Return for landing and await a steady green"], 0, "Steady red = give way and keep circling. Flashing red = don't land."),
  Q("light-signals", "What does a series of green flashes directed at an aircraft in flight mean?", ["Return for landing", "Cleared to land", "Cleared to taxi", "Aerodrome unsafe, do not land"], 0, "A steady green will follow."),
  Q("light-signals", "What does a series of red flashes directed at an aircraft in flight mean?", ["Aerodrome unsafe, do not land", "Give way to other aircraft and continue circling", "Return to starting point", "Land immediately"], 0, "Flashing red in the air = don't land here."),
  Q("light-signals", "What does a series of white flashes directed at an aircraft in flight mean?", ["Land at this aerodrome and proceed to the apron", "Return to starting point on the aerodrome", "Aerodrome unsafe, do not land", "Return for landing"], 0, "In the air: land and go to the apron. On the ground: return to the start."),
  Q("light-signals", "What does a red pyrotechnic light fired from the tower at an aircraft in flight mean?", ["Notwithstanding any previous instructions, do not land for the time being", "Cleared to land, but give way to other aircraft already in the circuit", "The aerodrome is closed permanently and you must divert immediately", "Return to the starting point and await further light signals"], 0, "Overrides any earlier instructions."),
  Q("light-signals", "What does a steady green light directed at an aircraft on the ground mean?", ["Cleared for take-off", "Cleared to taxi", "Return to starting point", "Stop"], 0, "Steady green on the ground = take-off."),
  Q("light-signals", "What does a series of green flashes directed at an aircraft on the ground mean?", ["Cleared to taxi", "Cleared for take-off", "Taxi clear of the landing area", "Stop"], 0, "Flashing green on the ground = taxi."),
  Q("light-signals", "What does a series of red flashes directed at an aircraft on the ground mean?", ["Taxi clear of the landing area in use", "Stop immediately and hold position", "Return to the starting point on the aerodrome", "Cleared for take-off from the runway in use"], 0, "Get off the landing area."),
  Q("light-signals", "What does a series of white flashes directed at an aircraft on the ground mean?", ["Return to starting point on the aerodrome", "Cleared to taxi to the runway in use", "Taxi to the apron and shut down", "Stop and hold your current position"], 0, "Back to where you started."),
  Q("light-signals", "What does a steady red light directed at an aircraft on the ground mean?", ["Stop", "Taxi clear of the landing area", "Return to starting point", "Give way to landing traffic"], 0, "Steady red on the ground = stop."),
  Q("light-signals", "Which light signal tells an aircraft in flight that it is cleared to land?", ["Steady green", "Series of green flashes", "Steady white", "Series of white flashes"], 0, "Green flashes = return for landing; steady green = cleared to land."),
  Q("light-signals", "Which light signal tells an aircraft on the ground that it is cleared to taxi?", ["Series of green flashes", "Steady green", "Series of white flashes", "Steady white"], 0, "Steady green on the ground is take-off, not taxi."),
  Q("light-signals", "How does a pilot in flight acknowledge a light signal by day?", ["Rock the wings", "Flash the landing lights twice", "Move the ailerons", "Switch the navigation lights on and off"], 0, "Rock the wings — but not on base leg or final."),
  Q("light-signals", "How does a pilot in flight acknowledge a light signal at night?", ["Flash the landing lights twice", "Rock the wings twice", "Move the rudder from side to side", "Fire a green pyrotechnic light"], 0, "Or the nav lights twice if there are no landing lights."),
  Q("light-signals", "How does a pilot on the ground acknowledge a light signal by day?", ["Move the ailerons or rudder", "Rock the wings", "Flash the landing lights twice", "Open the canopy"], 0, "Wiggle the controls."),
  Q("light-signals", "What does an aircraft repeatedly switching its landing lights on and off signal?", ["It must land but does not need immediate assistance", "It needs immediate assistance and is in grave danger", "It acknowledges a light signal from the tower", "It requests a steady green light to land"], 0, "That's an urgency signal. A red flare from the aircraft = distress."),

  Q("declared-distances", "TORA is the length of runway available for the:", ["ground run of an aeroplane taking off", "take-off run plus clearway", "take-off run plus stopway", "ground run of an aeroplane landing"], 0, "TORA = take-off run available."),
  Q("declared-distances", "TODA is equal to:", ["TORA plus clearway", "TORA plus stopway", "TORA minus the displaced threshold", "TORA plus stopway plus clearway"], 0, "Clearway climbs."),
  Q("declared-distances", "ASDA (EDA in the UK) is equal to:", ["TORA plus stopway", "TORA plus clearway", "LDA plus stopway", "TODA plus stopway"], 0, "Stopway stops."),
  Q("declared-distances", "A displaced threshold normally reduces the:", ["LDA", "TORA", "TODA", "ASDA"], 0, "The displaced section is still usable for take-off."),
  Q("declared-distances", "A runway is 900 m long with a 60 m stopway and a 200 m clearway. What are the TODA and ASDA?", ["TODA 1,100 m, ASDA 960 m", "TODA 960 m, ASDA 1,100 m", "TODA 1,160 m, ASDA 1,160 m", "TODA 900 m, ASDA 900 m"], 0, "TODA = 900 + 200; ASDA = 900 + 60."),
  Q("declared-distances", "A runway is 800 m long with its landing threshold displaced by 150 m. What are the TORA and LDA?", ["TORA 800 m, LDA 650 m", "TORA 650 m, LDA 800 m", "TORA 650 m, LDA 650 m", "TORA 950 m, LDA 800 m"], 0, "TORA is the full runway; LDA = 800 − 150."),
  Q("declared-distances", "A stopway is an area beyond the end of the TORA that is:", ["able to support an aircraft during an abandoned take-off", "free of obstacles for the initial climb", "located before a displaced threshold", "used for holding before take-off"], 0, "The stopway must bear the aircraft's weight; a clearway need not."),
  Q("declared-distances", "A clearway is an area beyond the end of the TORA that is:", ["free of obstacles for the initial climb", "able to support an aircraft during an abandoned take-off", "marked with yellow chevrons", "used for engine run-ups"], 0, "Clearway = obstacle-free climb-out area."),

  Q("ground-right-of-way", "Two aircraft are taxiing head-on towards each other. What should they do?", ["Both stop or, where practicable, alter course to the right", "Both stop or, where practicable, alter course to the left", "The aircraft with the other on its right gives way", "The heavier aircraft has right of way and continues"], 0, "Head-on on the ground: stop, or turn right."),
  Q("ground-right-of-way", "Two aircraft are taxiing on converging courses. Which gives way? The aircraft:", ["that has the other on its right", "that has the other on its left", "that is larger", "nearest the runway"], 0, "Same as in the air."),
  Q("ground-right-of-way", "When one taxiing aircraft is overtaking another, which has the right of way? The aircraft:", ["being overtaken", "overtaking", "on the left", "nearest the runway"], 0, "The overtaking aircraft keeps well clear."),
  Q("ground-right-of-way", "An aircraft taxiing on the manoeuvring area must give way to aircraft:", ["taking off or landing", "being towed", "parked on the apron", "on its left"], 0, "Taking off/landing aircraft have priority."),
  Q("ground-right-of-way", "In the UK, vehicles that are not towing aircraft must give way to:", ["aircraft and vehicles towing aircraft", "aircraft taking off and landing only", "emergency vehicles only", "no other aircraft or vehicles"], 0, "Order: taking off/landing → taxiing → vehicles towing aircraft → other vehicles."),
  Q("ground-right-of-way", "Without further clearance, what must you do at a runway-holding position?", ["Stop and hold", "Proceed if the runway looks clear", "Line up but not take off", "Cross if no aircraft is on final"], 0, "Stop and hold unless cleared further."),

  Q("airfield-signage", "A sign with white characters on a red background is a:", ["mandatory instruction sign", "location sign", "direction sign", "destination information sign"], 0, "Red = mandatory."),
  Q("airfield-signage", "A sign with yellow characters on a black background is a:", ["location sign", "direction sign", "mandatory instruction sign", "distance remaining sign"], 0, "Black = 'you are here'."),
  Q("airfield-signage", "A sign with black characters and an arrow on a yellow background is a:", ["direction sign", "location sign", "mandatory instruction sign", "no entry sign"], 0, "Yellow = which way to go."),
  Q("airfield-signage", "What does a sign showing '09-27' in white on red beside a taxiway indicate?", ["A runway-holding position for runway 09/27", "Directions to the threshold of runway 09/27", "You are now on runway 09/27", "Runway 09/27 is closed to all traffic"], 0, "A mandatory runway designation sign."),
  Q("airfield-signage", "What does a red sign showing a white circle with a horizontal bar indicate?", ["No entry", "Stop and hold", "Runway ahead", "One-way taxiway"], 0, "The NO ENTRY mandatory sign."),
  Q("airfield-signage", "Where would you see a runway vacated sign?", ["When leaving the runway", "Before entering the runway", "At the runway threshold", "At the apron entrance"], 0, "Once past it, you are clear of the runway area."),
  Q("airfield-signage", "What does a sign showing a white number on a black background beside the runway indicate?", ["Runway distance remaining", "The runway designator", "The taxiway designator", "A mandatory holding position"], 0, "Thousands of feet (or metres) of runway left."),

  Q("aerodrome-markings", "A runway designated '27' is aligned with approximately:", ["270° magnetic", "270° true", "027° magnetic", "027° true"], 0, "Magnetic direction ÷ 10."),
  Q("aerodrome-markings", "What do white arrows on the runway centreline leading to a threshold bar indicate?", ["A displaced threshold — usable for take-off but not for landing", "A pre-threshold area — not usable for any aircraft movement", "A taxiway crossing — give way to taxiing aircraft", "A stopway — usable only for an abandoned take-off"], 0, "Don't touch down before the threshold bar."),
  Q("aerodrome-markings", "What do yellow chevrons before the start of a runway indicate?", ["An area not usable for normal aircraft movement", "A displaced threshold usable for take-off", "A runway-holding position", "A closed taxiway"], 0, "Blast pads and stopways."),
  Q("aerodrome-markings", "At a Pattern A runway-holding position, an aircraft approaching the runway should stop at the:", ["solid lines", "dashed lines", "gap between the solid and dashed lines", "mandatory sign only"], 0, "Solid = stop. The dashed side faces the runway."),
  Q("aerodrome-markings", "What does a 'ladder' pattern (Pattern B) holding position indicate?", ["An ILS / CAT II/III holding position", "An intermediate holding position", "A closed taxiway", "The end of a stopway"], 0, "Pattern B protects the ILS sensitive area."),
  Q("aerodrome-markings", "What does a white cross on a runway indicate?", ["The runway is closed", "A runway intersection", "A helicopter landing area", "The aiming point"], 0, "White X on a runway, yellow X on a taxiway = closed."),
  Q("aerodrome-markings", "What colour are taxiway centreline markings?", ["Yellow", "White", "Blue", "Orange"], 0, "Taxiway markings yellow; runway markings white."),
  Q("aerodrome-markings", "The number of stripes in runway threshold markings indicates the runway's:", ["width", "length", "strength", "approach category"], 0, "E.g. 8 stripes for a 30 m wide runway."),
  Q("aerodrome-markings", "What does a single dashed yellow line across a taxiway indicate?", ["An intermediate holding position", "A runway-holding position", "The taxiway edge", "A closed taxiway"], 0, "Intermediate holding positions use a single dashed line."),
  Q("registration-marks", "What is the minimum height for aircraft underwing markings?", ["50 cm", "20 cm", "60 cm", "30 cm"], 0, "Underwing marks: at least 50 cm. Fuselage/vertical tail marks: at least 30 cm (the distractor)."),
  Q("registration-marks", "What is the minimum height for registration marks on the fuselage or vertical tail of an aeroplane?", ["30 cm", "50 cm", "15 cm", "60 cm"], 0, "30 cm on the fuselage/tail; 50 cm under the wings."),
  Q("registration-marks", "UK aircraft are registered by the:", ["CAA", "Department for Transport", "ICAO", "aircraft manufacturer"], 0, "The CAA keeps the UK register and issues the Certificate of Registration."),
  Q("registration-marks", "The nationality mark of a UK-registered aircraft is:", ["G", "UK", "GB", "EG"], 0, "UK marks are G- followed by four letters. EG is the ICAO location prefix for UK aerodromes — a trap."),
  Q("registration-marks", "An aircraft's fireproof identification plate must show its:", ["nationality and registration marks", "maximum take-off weight", "date of last maintenance", "owner's name and address"], 0, "The identification plate carries the nationality and registration marks."),

  Q("altimeter-settings", "With QFE set, the altimeter reads:", ["height above the aerodrome", "altitude above mean sea level", "flight level", "height above the highest obstacle"], 0, "QFE → height; QNH → altitude; 1013 → flight level."),
  Q("altimeter-settings", "With QNH set, the altimeter reads:", ["altitude above mean sea level", "height above the aerodrome", "flight level", "pressure altitude"], 0, "QNH gives altitude."),
  Q("altimeter-settings", "With 1013 hPa set, the altimeter reads:", ["flight level (pressure altitude)", "altitude above mean sea level", "height above the aerodrome", "density altitude"], 0, "Standard pressure gives pressure altitude, expressed as a flight level."),
  Q("altimeter-settings", "The Regional Pressure Setting is the:", ["lowest forecast QNH for the altimeter setting region for the hour", "highest forecast QNH for the region for the hour", "average QNH for the region over the day", "QFE of the main aerodrome in the region"], 0, "Using the lowest forecast QNH gives a conservative (low) altitude reading."),
  Q("altimeter-settings", "You fly from an area of high pressure to low pressure without resetting the altimeter. The aircraft will be:", ["lower than indicated", "higher than indicated", "at the indicated altitude", "at the indicated height above ground"], 0, "High to low, look out below."),

  Q("transition", "In the UK, the transition altitude is normally:", ["3,000 ft", "6,000 ft", "4,000 ft", "18,000 ft"], 0, "Normally 3,000 ft, higher in and around some major controlled airspace."),
  Q("transition", "The transition level is the:", ["lowest flight level available for use above the transition altitude", "highest altitude at which QNH may be used for cruising", "level at which QFE is changed to QNH on descent", "lowest level at which VFR flights are permitted"], 0, "TL = lowest usable FL above the TA."),
  Q("transition", "When climbing through the transition altitude, you should set:", ["1013 hPa", "QNH", "QFE", "the Regional Pressure Setting"], 0, "Climbing: change to 1013 at the TA."),
  Q("transition", "When descending through the transition level, you should set:", ["QNH", "1013 hPa", "QFE", "the Regional Pressure Setting"], 0, "Descending: change to QNH at the TL."),
  Q("transition", "The airspace between the transition altitude and the transition level is the:", ["transition layer", "transition zone", "transition band", "altimeter setting region"], 0, "Don't cruise in the transition layer."),

  Q("cruising-levels", "An IFR flight on a magnetic track of 090° should cruise at:", ["an odd flight level, e.g. FL50", "an even flight level, e.g. FL60", "an odd flight level plus 500 ft, e.g. FL55", "an even flight level plus 500 ft, e.g. FL65"], 0, "000°–179°: odd for IFR."),
  Q("cruising-levels", "A VFR flight on a magnetic track of 270° should cruise at:", ["an even flight level plus 500 ft, e.g. FL65", "an odd flight level plus 500 ft, e.g. FL55", "an even flight level, e.g. FL60", "an odd flight level, e.g. FL50"], 0, "180°–359°: even; VFR adds 500 ft."),
  Q("cruising-levels", "A VFR flight on a magnetic track of 175° should cruise at:", ["FL55", "FL60", "FL65", "FL50"], 0, "175° is in 000°–179°: odd + 500 for VFR."),
  Q("cruising-levels", "Cruising levels under the semicircular rule are based on:", ["magnetic track", "magnetic heading", "true track", "true heading"], 0, "Magnetic TRACK."),
  Q("cruising-levels", "Which rule does the UK now use for cruising levels?", ["The semicircular rule", "The quadrantal rule", "The hemispherical heading rule", "No rule — any level may be used"], 0, "The quadrantal rule was replaced by the SERA semicircular rule in 2015."),

  Q("airspace-classes", "VFR flight is not permitted in Class:", ["A", "C", "D", "E"], 0, "Class A is IFR only."),
  Q("airspace-classes", "A VFR flight in Class D airspace requires:", ["an ATC clearance", "only a listening watch", "a flight plan filed 60 minutes before", "nothing — VFR is uncontrolled"], 0, "VFR in C and D needs a clearance."),
  Q("airspace-classes", "In Class D airspace, ATC separate:", ["IFR flights from other IFR flights", "all flights from each other", "VFR flights from other VFR flights", "no flights at all"], 0, "In D, VFR get traffic information but aren't separated from VFR."),
  Q("airspace-classes", "In Class E airspace, an ATC clearance is required for:", ["IFR flights only", "VFR flights only", "both IFR and VFR flights", "neither IFR nor VFR flights"], 0, "Class E: clearance for IFR only."),
  Q("airspace-classes", "Which classes of airspace are not currently used in the UK?", ["B and F", "A and C", "D and E", "C and G"], 0, "The UK uses A, C, D, E and G."),
  Q("airspace-classes", "Class G airspace is:", ["uncontrolled", "controlled, VFR only", "controlled, IFR only", "prohibited to IFR flights"], 0, "Class G = uncontrolled."),

  Q("controlled-airspace-structures", "A control zone (CTR) extends upwards from:", ["the surface", "1,000 ft above the surface", "the transition altitude", "a specified base above the surface"], 0, "CTRs start at the surface; CTAs start at a base above it."),
  Q("controlled-airspace-structures", "A control area (CTA) extends upwards from:", ["a specified base above the surface", "the surface, like a control zone", "FL195, the base of upper airspace", "the transition level for the area"], 0, "A CTA has a base above the surface."),
  Q("controlled-airspace-structures", "An airway is a control area in the form of a:", ["corridor", "circle around an aerodrome", "cylinder from the surface", "zone around a danger area"], 0, "Airways are corridors, normally 10 nm wide in the UK."),
  Q("controlled-airspace-structures", "A CTA has a base of 2,500 ft. You fly beneath it at 2,000 ft on QNH in Class G. You need:", ["no clearance", "a clearance from the CTA controller", "a Special VFR clearance", "a flight plan"], 0, "Flying under a CTA in Class G needs no clearance."),

  Q("atz", "An ATZ around an aerodrome whose longest runway is 1,800 m has a radius of:", ["2 nm", "2.5 nm", "3 nm", "5 nm"], 0, "2 nm if the longest runway is 1,850 m or less; 2.5 nm if longer."),
  Q("atz", "An ATZ around an aerodrome whose longest runway is 2,000 m has a radius of:", ["2.5 nm", "2 nm", "3 nm", "5 nm"], 0, "Longest runway over 1,850 m → 2.5 nm."),
  Q("atz", "The vertical extent of an ATZ is from the surface to:", ["2,000 ft above aerodrome level", "3,000 ft above aerodrome level", "2,000 ft above mean sea level", "1,500 ft above aerodrome level"], 0, "2,000 ft aal. 3,000 ft aal is a MATZ."),
  Q("atz", "An ATZ is centred on the:", ["midpoint of the longest runway", "control tower", "aerodrome reference point", "threshold of the main runway"], 0, "Midpoint of the longest runway."),
  Q("atz", "To fly in an ATZ where an ATC unit is operating, you must obtain:", ["permission from the ATC unit", "information from the ATC unit", "a Special VFR clearance", "a flight plan"], 0, "ATC → permission. AFIS/AGCS → information."),
  Q("atz", "To fly in an ATZ with an AFIS or AGCS unit, you must obtain:", ["information to make the flight safely", "permission from the AFIS officer", "a clearance from the nearest ATC unit", "prior permission by telephone"], 0, "AFIS and AGCS can't give permission — you get information."),

  Q("special-use-airspace", "A MATZ normally extends from the surface to:", ["3,000 ft above aerodrome level within 5 nm", "2,000 ft above aerodrome level within 2 nm", "3,000 ft above aerodrome level within 2.5 nm", "2,000 ft above aerodrome level within 5 nm"], 0, "MATZ: 5 nm radius, surface to 3,000 ft aal, plus stubs."),
  Q("special-use-airspace", "For a civil pilot, obtaining a MATZ penetration service is:", ["not compulsory, but strongly recommended", "compulsory at all times", "compulsory only at night", "prohibited for civil aircraft"], 0, "Not mandatory for civil pilots (the ATZ inside it is)."),
  Q("special-use-airspace", "An area marked 'EG D' on a chart is a:", ["danger area", "designated area", "departure area", "defence area"], 0, "P = prohibited, R = restricted, D = danger."),
  Q("special-use-airspace", "In a Transponder Mandatory Zone (TMZ), aircraft must:", ["carry and operate a suitable transponder", "maintain two-way radio contact", "obtain an ATC clearance", "fly IFR only"], 0, "TMZ = transponder; RMZ = radio."),
  Q("special-use-airspace", "In a Radio Mandatory Zone (RMZ), aircraft must:", ["carry a radio and maintain a listening watch", "carry and operate a transponder", "obtain an ATC clearance", "fly above 3,000 ft"], 0, "RMZ: call up and listen out."),

  Q("speed-limits", "What is the maximum indicated airspeed allowed for a VFR flight at FL70 in Class D airspace?", ["250 kt", "220 kt", "150 kt", "125 kt"], 0, "Below FL100 in Class D, 250 kt IAS applies to IFR and VFR."),
  Q("speed-limits", "The 250 kt speed limit below FL100 does NOT apply to:", ["IFR flights in Class C", "VFR flights in Class C", "IFR flights in Class D", "VFR flights in Class G"], 0, "In Class C, the limit applies to VFR only; Class A has no limit."),
  Q("speed-limits", "The maximum IAS for a VFR flight at 2,000 ft in Class G airspace is:", ["250 kt", "140 kt", "200 kt", "No limit"], 0, "250 kt below FL100 in Class G."),

  Q("air-traffic-services", "The three air traffic services are:", ["air traffic control, flight information and alerting", "air traffic control, radar and search and rescue", "approach, tower and ground", "Basic, Traffic and Deconfliction"], 0, "ATC, FIS and the alerting service."),
  Q("air-traffic-services", "Which UK Flight Information Service provides deconfliction advice?", ["Deconfliction Service", "Traffic Service", "Basic Service", "Procedural Service only"], 0, "Only the Deconfliction Service gives avoiding-action advice (the Procedural Service deconflicts without surveillance)."),
  Q("air-traffic-services", "Under a Traffic Service, who is responsible for collision avoidance? The:", ["pilot", "controller", "pilot and controller equally", "aircraft with right of way"], 0, "Under all UK FIS services the pilot remains responsible."),
  Q("air-traffic-services", "Under a Basic Service, the controller:", ["is not expected to provide traffic information", "provides deconfliction advice", "separates you from all other traffic", "provides surveillance-based traffic information"], 0, "Basic Service gives general information; traffic info isn't normally provided."),
  Q("air-traffic-services", "The alerting service is provided to:", ["notify organisations about aircraft needing search and rescue", "warn pilots about deteriorating weather on their route", "separate IFR flights from each other in controlled airspace", "publish NOTAMs about short-notice airspace changes"], 0, "Alerting service → SAR."),

  Q("aerodrome-services", "An aerodrome station with the call sign 'Radio' provides a(n):", ["Air/Ground Communication Service", "Aerodrome Flight Information Service", "Air Traffic Control service", "Approach control service"], 0, "Radio = AGCS; Information = AFIS; Tower = ATC."),
  Q("aerodrome-services", "An aerodrome station with the call sign 'Information' provides a(n):", ["Aerodrome Flight Information Service", "Air/Ground Communication Service", "Air Traffic Control service", "Distress and Diversion service"], 0, "Information = AFIS."),
  Q("aerodrome-services", "An AFIS officer tells you the runway is clear. Landing is:", ["at your discretion", "cleared", "approved", "not permitted"], 0, "AFIS can't issue landing clearances — 'land at your discretion'."),
  Q("aerodrome-services", "Which aerodrome service can issue landing clearances?", ["ATC", "AFIS", "AGCS", "SafetyCom"], 0, "Only ATC issues clearances."),

  Q("flight-plans", "A flight plan should be filed at least:", ["60 minutes before departure", "30 minutes before departure", "2 hours before departure", "24 hours before departure"], 0, "SERA.4001: at least 60 minutes before departure."),
  Q("flight-plans", "For a controlled flight, the flight plan must be amended or refiled if departure is delayed by:", ["30 minutes", "15 minutes", "1 hour", "2 hours"], 0, "30 minutes for controlled flights; 1 hour for uncontrolled flights."),
  Q("flight-plans", "For an uncontrolled flight, the flight plan must be amended or refiled if departure is delayed by:", ["1 hour", "30 minutes", "15 minutes", "2 hours"], 0, "1 hour for uncontrolled flights."),
  Q("flight-plans", "Which of these flights requires a flight plan?", ["A flight crossing an international border", "A local VFR flight in Class G", "A circuit at a non-radio aerodrome", "A VFR flight below a CTA"], 0, "Crossing an international border requires a flight plan."),
  Q("flight-plans", "Times in a flight plan are given in:", ["UTC", "local time", "BST", "the time zone of the destination"], 0, "Flight plan times are UTC."),

  Q("transponder-codes", "What transponder code indicates an emergency?", ["7700", "7600", "7500", "7000"], 0, "77 = emergency."),
  Q("transponder-codes", "What transponder code indicates radio failure?", ["7600", "7700", "7500", "2000"], 0, "76 = radio failure."),
  Q("transponder-codes", "What transponder code indicates unlawful interference?", ["7500", "7600", "7700", "7000"], 0, "75 = hijack."),
  Q("transponder-codes", "In the UK, the conspicuity code is:", ["7000", "2000", "1200", "0000"], 0, "1200 is the US VFR code — a trap."),
  Q("transponder-codes", "Mode C transmits the aircraft's identity code and its:", ["pressure altitude", "altitude on QNH", "height on QFE", "unique aircraft address"], 0, "Mode C altitude is always referenced to 1013 hPa. A unique address is Mode S."),

  Q("customs-immigration", "A General Aviation Report for an international flight must be submitted:", ["no earlier than 48 hours and no later than 2 hours before departure", "no earlier than 24 hours and no later than 4 hours before departure", "no later than 12 hours before departure", "on arrival, within 2 hours of landing"], 0, "The GAR window is 48 h to 2 h before departure, online."),
  Q("customs-immigration", "A General Aviation Report must be submitted:", ["online, via Submit-a-GAR or an approved app", "by email to Border Force", "by fax to the destination aerodrome", "on paper to the aerodrome operator"], 0, "Emailed GARs are no longer accepted."),
  Q("customs-immigration", "The Common Travel Area includes the UK, the Isle of Man, the Channel Islands and:", ["Ireland", "France", "Belgium", "Iceland"], 0, "UK, Ireland, Channel Islands and Isle of Man."),
  Q("customs-immigration", "A flight within the Common Travel Area using an aerodrome not designated for police purposes must notify the police:", ["12 hours before departure or arrival", "2 hours before departure", "48 hours before departure", "on arrival"], 0, "12 hours' notice to the police."),
  Q("customs-immigration", "Which Article of the Chicago Convention deals with preventing the spread of disease?", ["Article 14", "Article 13", "Article 10", "Article 24"], 0, "Article 14 — prevention of spread of disease."),

  Q("aviation-security", "Who is responsible for the security of an aircraft and its occupants during flight? The:", ["pilot-in-command", "aerodrome operator", "Border Force", "aircraft owner"], 0, "A PIC responsibility."),
  Q("aviation-security", "In flight, a pilot subject to unlawful interference should squawk:", ["7500", "7600", "7700", "7000"], 0, "7500 = unlawful interference."),
  Q("aviation-security", "When leaving an aircraft unattended, the pilot should:", ["lock it and remove the keys", "leave the keys in the ignition for the next pilot", "leave the doors open to ventilate it", "inform ATC"], 0, "Secure unattended aircraft."),

  Q("vmc-minima", "What is the minimum flight visibility for VFR flight at or above FL100?", ["8 km", "5 km", "1,500 m", "10 km"], 0, "8 km at/above FL100; 5 km below."),
  Q("vmc-minima", "What is the minimum flight visibility for VFR flight below FL100 in Class C airspace?", ["5 km", "8 km", "1,500 m", "3 km"], 0, "5 km below FL100."),
  Q("vmc-minima", "In controlled airspace below FL100, a VFR flight must stay at least how far from cloud?", ["1,500 m horizontally and 1,000 ft vertically", "1,000 m horizontally and 1,500 ft vertically", "1,500 m horizontally and 500 ft vertically", "clear of cloud, with the surface in sight"], 0, "1,500 m / 1,000 ft."),
  Q("vmc-minima", "In UK Class G airspace, by day, at or below 3,000 ft AMSL and 140 kt or less, the VMC minima are:", ["1,500 m flight visibility, clear of cloud, surface in sight", "5 km flight visibility, clear of cloud, surface in sight", "5 km flight visibility, 1,500 m and 1,000 ft from cloud", "8 km flight visibility, 1,500 m and 1,000 ft from cloud"], 0, "UK alternative for Class F/G."),
  Q("vmc-minima", "In UK Class D airspace, by day, at or below 3,000 ft AMSL and 140 kt or less, the VMC minima are:", ["5 km flight visibility, clear of cloud, surface in sight", "1,500 m flight visibility, clear of cloud, surface in sight", "8 km flight visibility, clear of cloud", "5 km flight visibility, 1,500 m and 1,000 ft from cloud"], 0, "UK Class D alternative: 5 km, clear of cloud, surface in sight."),

  Q("special-vfr", "Which of these is a requirement for a Special VFR flight?", ["Airspeed of 140 kt or less", "Airspeed of 125 kt or less", "Minimum flight visibility of at least 8,000 m", "Minimum flight visibility of at least 5,000 m"], 0, "SVFR: 140 kt IAS or less, clear of cloud, surface in sight, 1,500 m flight visibility."),
  Q("special-vfr", "Special VFR may be granted only within a:", ["control zone", "control area", "danger area", "MATZ"], 0, "SVFR is a CTR clearance."),
  Q("special-vfr", "The minimum flight visibility for a Special VFR flight in an aeroplane is:", ["1,500 m", "800 m", "5 km", "3 km"], 0, "800 m applies to helicopters."),
  Q("special-vfr", "A Special VFR flight must remain:", ["clear of cloud and with the surface in sight", "1,500 m horizontally and 1,000 ft vertically from cloud", "above 1,000 ft above the highest obstacle", "in contact with the nearest AFIS unit"], 0, "Clear of cloud, surface in sight."),

  Q("vfr-rules", "VFR flights must not be operated above:", ["FL195", "FL100", "FL245", "FL660"], 0, "No VFR above FL195."),
  Q("vfr-rules", "To fly VFR at night, a UK PPL holder must hold a:", ["night rating (or instrument rating)", "Class 1 medical certificate", "FRTOL with night endorsement", "IR(R) only"], 0, "A night rating (or IR)."),
  Q("vfr-rules", "A VFR flight in Class C airspace requires:", ["an ATC clearance and two-way radio", "a Special VFR clearance", "a transponder only", "nothing — VFR is exempt"], 0, "C and D: clearance and radio."),

  Q("ifr-rules", "Except for take-off and landing, an IFR flight must not fly below:", ["1,000 ft above the highest obstacle within 8 km", "500 ft above the highest obstacle within 150 m", "1,500 ft above the highest obstacle within 5 nm", "2,000 ft above the highest obstacle within 5 km"], 0, "SERA.5015 (2,000 ft over high terrain)."),
  Q("ifr-rules", "To change from IFR to VFR, the pilot should:", ["tell ATS 'cancelling my IFR flight' while in VMC", "wait for ATC to suggest changing to VFR", "squawk 7000 and continue without telling ATS", "file a new VFR flight plan before changing"], 0, "Only in VMC, expected to remain VMC; ATC won't suggest it."),
  Q("ifr-rules", "The UK IR(R) allows flight under IFR in:", ["UK airspace except Class A", "all airspace worldwide", "Class A airspace only", "Class G airspace only"], 0, "IR(R) = UK airspace, not Class A."),

  Q("ppl-privileges", "The holder of a PPL(A) may act as pilot-in-command:", ["without remuneration in non-commercial operations", "for remuneration in commercial operations", "for remuneration on flights under 1 hour", "only with an instructor on board"], 0, "No remuneration, non-commercial operations."),
  Q("ppl-privileges", "On a cost-sharing flight, the direct costs must be shared by:", ["all occupants, including the pilot, with no more than 6 people on board", "the passengers only, with no more than 4 people on board", "all occupants, including the pilot, with no more than 4 people on board", "the passengers only, with no more than 6 people on board"], 0, "Including the pilot; maximum 6 persons."),
  Q("ppl-privileges", "The minimum age to hold a PPL(A) is:", ["17", "16", "18", "21"], 0, "16 for first solo; 17 for the licence."),
  Q("ppl-privileges", "When exercising the privileges of a licence, the pilot must carry the licence, the medical certificate and:", ["a personal identification document with a photo", "the pilot's personal flying log book", "the aircraft's current weight schedule", "proof of address dated within 3 months"], 0, "FCL.045: licence, medical and photo ID."),

  Q("medical-certificates", "A Class 2 medical certificate for a pilot of 43 years old is valid for:", ["24 months", "12 months", "60 months", "Indefinitely"], 0, "Age 40–49: 24 months."),
  Q("medical-certificates", "A Class 2 medical certificate for a pilot aged 35 is valid for:", ["60 months", "24 months", "12 months", "36 months"], 0, "Under 40: 60 months (ending at the 42nd birthday)."),
  Q("medical-certificates", "A Class 2 medical certificate for a pilot aged 55 is valid for:", ["12 months", "24 months", "60 months", "6 months"], 0, "50 and over: 12 months."),
  Q("medical-certificates", "A pilot discovers she is pregnant. She should:", ["seek aeromedical advice without undue delay", "stop flying permanently", "continue flying without telling anyone", "apply for a Class 1 medical"], 0, "Pregnancy is one of the triggers to seek aeromedical advice."),
  Q("medical-certificates", "A Class 2 medical issued to a pilot aged 39 will end, at the latest, on their:", ["42nd birthday", "40th birthday", "44th birthday", "41st birthday"], 0, "Certificates issued before 40 cease at the 42nd birthday."),

  Q("class-ratings", "An SEP class rating is valid for:", ["24 months", "12 months", "36 months", "60 months"], 0, "Two years, counted from the end of the month of the skill test."),
  Q("class-ratings", "If you pass your SEP skill test on 10 March 2025 and do nothing to revalidate it, what is the last day you can fly on that rating?", ["31 March 2027", "9 March 2027", "10 March 2027", "31 March 2026"], 0, "The 24 months run from the end of the calendar month of the test (CAA guidance)."),
  Q("class-ratings", "To revalidate an SEP rating by experience, you need within the 12 months before expiry:", ["12 hours, including 6 hours as PIC, 12 take-offs and landings, and 1 hour with an instructor", "6 hours, including 3 hours as PIC, 6 take-offs and landings, and 1 hour with an instructor", "12 hours, including 6 hours as PIC, 6 take-offs and landings, and 2 hours with an instructor", "10 hours, including 5 hours as PIC, 10 take-offs and landings, and 1 hour with an instructor"], 0, "12-6-12-1."),
  Q("class-ratings", "A proficiency check to revalidate an SEP rating must be taken within:", ["the 3 months before the expiry date", "the 6 months before the expiry date", "the 12 months before the expiry date", "the month after the expiry date"], 0, "Within 3 months before expiry."),

  Q("recency", "To carry passengers, a pilot must have made at least 3 take-offs and landings in the same type or class within the preceding:", ["90 days", "60 days", "30 days", "6 months"], 0, "3 in 90."),
  Q("recency", "To carry passengers at night, how many of the 3 recent take-offs and landings must have been at night?", ["1", "2", "3", "None"], 0, "At least one at night (unless holding an IR)."),
  Q("recency", "For passenger-carrying recency, the take-offs and landings must have been made as:", ["the sole manipulator of the controls", "a passenger", "a student under instruction only", "PIC in any aircraft type"], 0, "Sole manipulator, same type or class."),

  Q("other-ratings", "For a night rating, how many solo take-offs and full-stop landings must be made at night?", ["5", "3", "10", "1"], 0, "5 solo take-offs and 5 solo full-stop landings."),
  Q("other-ratings", "The night rating requires at least how many hours of flight time at night?", ["5", "3", "10", "15"], 0, "5 hours, including 3 dual (with 1 hour of navigation)."),
  Q("other-ratings", "The UK IR(R) does NOT allow flight in:", ["Class A airspace", "Class D airspace", "Class G airspace", "IMC"], 0, "Not Class A."),

  Q("pic-responsibilities", "Who has final authority over the disposition of the aircraft while in command? The:", ["pilot-in-command", "aircraft owner", "air traffic controller", "aerodrome operator"], 0, "SERA.2010."),
  Q("pic-responsibilities", "A passenger refuses to follow a safety instruction from the PIC. Passengers must:", ["obey the lawful commands of the PIC for safety", "follow only instructions from ATC", "only follow instructions they agree with", "follow only the aircraft owner"], 0, "All persons on board obey the PIC's lawful commands."),
  Q("pic-responsibilities", "In an emergency requiring immediate action, the PIC may:", ["depart from rules as necessary for safety, and report it afterwards", "only follow instructions given by ATC, without deviating", "only act once ATC has approved the planned action", "never deviate from the rules of the air, whatever happens"], 0, "Safety comes first; report afterwards."),

  Q("fuel-planning", "For a VFR flight by day in an aeroplane, the minimum fuel reserve after reaching the destination is:", ["30 minutes at normal cruising altitude", "45 minutes at normal cruising altitude", "20 minutes at normal cruising altitude", "60 minutes at normal cruising altitude"], 0, "Day VFR: 30 minutes."),
  Q("fuel-planning", "For a VFR flight at night in an aeroplane, the minimum fuel reserve after reaching the destination is:", ["45 minutes at normal cruising altitude", "30 minutes at normal cruising altitude", "60 minutes at normal cruising altitude", "90 minutes at normal cruising altitude"], 0, "Night VFR: 45 minutes."),
  Q("fuel-planning", "A day VFR flight is planned to take 1 hour 20 minutes. The minimum fuel to plan is enough for:", ["1 hour 50 minutes", "1 hour 20 minutes", "2 hours 5 minutes", "1 hour 40 minutes"], 0, "Flight time + 30 minutes (plus taxi and contingency in practice)."),

  Q("fitness-alcohol", "The UK legal blood alcohol limit for pilots is:", ["20 mg per 100 ml of blood", "80 mg per 100 ml of blood", "50 mg per 100 ml of blood", "9 mg per 100 ml of blood"], 0, "20 mg/100 ml blood (9 micrograms/100 ml breath)."),
  Q("fitness-alcohol", "A pilot is below the legal alcohol limit but feels its effects. The pilot should:", ["not fly", "fly, as they are below the limit", "fly with a passenger to help", "fly only locally"], 0, "Impairment, not just the legal limit, matters."),
  Q("fitness-alcohol", "A person who is drunk:", ["must not enter an aircraft", "may fly as a passenger if accompanied", "may fly as a passenger on short flights", "may enter an aircraft but not fly it"], 0, "ANO: must not enter any aircraft when drunk."),

  Q("passenger-safety", "Passengers must have their seat belts fastened during:", ["taxi, take-off, landing and whenever the PIC considers it necessary", "take-off and landing only", "the whole flight except the cruise in smooth air", "taxiing only"], 0, "Taxi, take-off, landing, turbulence."),
  Q("passenger-safety", "Life jackets must be carried for everyone on board a single-engine landplane flying over water:", ["beyond gliding distance from land", "at any distance from land", "more than 50 nm from land", "more than 100 nm from land"], 0, "Beyond gliding distance from land."),
  Q("passenger-safety", "A pre-flight passenger briefing should cover:", ["seat belts, emergency exits and emergency equipment", "the aircraft's maintenance history", "the weight schedule", "the pilot's log book"], 0, "Belts, exits, equipment."),

  Q("endangering-safety", "Under the ANO, a person must not act in a manner likely to endanger an aircraft:", ["recklessly or negligently", "intentionally only", "while in flight only", "when carrying passengers only"], 0, "The offence wording is 'recklessly or negligently'."),
  Q("endangering-safety", "Which of these may be dropped from an aircraft as ballast?", ["Fine sand or water", "Gravel or stones", "Any article under 1 kg", "Fuel at any time"], 0, "Ballast only as fine sand or water; fuel only in an emergency."),
  Q("endangering-safety", "Fuel may be jettisoned from an aircraft:", ["in an emergency", "at any time over open country", "only over the sea at any time", "never"], 0, "Jettisoning fuel is permitted in an emergency."),

  Q("oxygen-equipment", "The pilot must use supplemental oxygen when the cabin pressure altitude exceeds:", ["10,000 ft for more than 30 minutes, and always above 13,000 ft", "8,000 ft for more than 30 minutes, and always above 10,000 ft", "13,000 ft for more than 30 minutes, and always above 15,000 ft", "10,000 ft for more than 60 minutes, and always above 12,000 ft"], 0, "Part-NCO.OP.190."),
  Q("oxygen-equipment", "Instead of a fixed ELT, a small aeroplane with up to 6 seats may carry a:", ["PLB carried by a crew member or passenger", "handheld VHF radio carried by the pilot", "Mode S transponder fitted to the aircraft", "flare pistol carried in the cockpit"], 0, "A personal locator beacon may substitute."),

  Q("marshalling-signals", "From the cockpit, how do you signal to a marshaller to insert chocks?", ["Arms extended with palms outwards, move hands inwards to cross in front of face.", "Hands crossed in front of face, palms outwards, then move arms outwards.", "Raise arm and hand with fist clenched horizontally in front of face, then extend fingers.", "Raise arm and hand with fingers extended horizontally in front of face, then clench fist."], 0, "Chocks IN: hands move IN to cross. Crossed hands moving out = remove chocks."),
  Q("marshalling-signals", "You signal to a marshaller by raising your arm and hand with fist clenched horizontally in front of face, then extending your fingers. What does it mean?", ["Brakes released", "Engine started", "Remove chocks", "Radio readability five"], 0, "Fist → open = let go of the brakes. Open → fist = brakes engaged."),
  Q("marshalling-signals", "From the cockpit, how do you signal to a marshaller that the brakes are engaged?", ["Raise arm and hand with fingers extended horizontally in front of face, then clench fist.", "Raise arm and hand with fist clenched horizontally in front of face, then extend fingers.", "Hands crossed in front of face, palms outwards, then move arms outwards.", "Arms extended with palms outwards, move hands inwards to cross in front of face."], 0, "Grab the brakes: open hand → fist."),
  Q("marshalling-signals", "You signal to a marshaller with your hands crossed in front of your face, palms outwards, then move your arms outwards. What does it mean?", ["Remove chocks", "Insert chocks", "Brakes released", "Brakes engaged"], 0, "Crossed hands moving out = chocks out."),
  Q("marshalling-signals", "A marshaller slowly moves fully extended arms from the sides to above the head until the wands cross. This means:", ["normal stop", "emergency stop", "cut engines", "chocks inserted"], 0, "Emergency stop is the same position reached abruptly."),
  Q("marshalling-signals", "A marshaller draws a wand across the throat in a slicing motion. This means:", ["cut engines", "normal stop", "slow down", "set brakes"], 0, "The slicing motion = cut engines."),

  Q("distress-urgency", "A distress message begins with:", ["MAYDAY MAYDAY MAYDAY", "PAN PAN, PAN PAN, PAN PAN", "SECURITÉ SECURITÉ SECURITÉ", "EMERGENCY EMERGENCY EMERGENCY"], 0, "MAYDAY = distress; PAN PAN = urgency."),
  Q("distress-urgency", "An urgency message begins with:", ["PAN PAN, PAN PAN, PAN PAN", "MAYDAY MAYDAY MAYDAY", "SECURITÉ SECURITÉ SECURITÉ", "URGENT URGENT URGENT"], 0, "PAN PAN ×3."),
  Q("distress-urgency", "The international aeronautical emergency frequency is:", ["121.5 MHz", "123.45 MHz", "135.48 MHz", "118.0 MHz"], 0, "121.5 MHz. 135.480 MHz is SafetyCom."),
  Q("distress-urgency", "An aircraft threatened by grave and imminent danger and requiring immediate assistance is in a state of:", ["distress", "urgency", "alert", "uncertainty"], 0, "Distress → MAYDAY."),
  Q("distress-urgency", "A red flare fired from an aircraft means:", ["it is in distress and requires immediate assistance", "it acknowledges a light signal", "it is compelled to land but needs no assistance", "it is about to land"], 0, "Red pyrotechnic from an aircraft = distress."),

  Q("emergency-phases", "What is the name of the emergency phase where there is reasonable certainty that an aircraft and its occupants are threatened by grave and imminent danger or require immediate assistance? The:", ["Distress phase", "Urgency phase", "Action phase", "Alert phase"], 0, "DETRESFA. 'Urgency' and 'Action' aren't alerting-service phases."),
  Q("emergency-phases", "An aircraft fails to arrive within 30 minutes of its ETA and there has been no contact. This begins the:", ["uncertainty phase", "alert phase", "distress phase", "action phase"], 0, "INCERFA."),
  Q("emergency-phases", "An aircraft cleared to land fails to land within 5 minutes of the estimated landing time and contact is lost. This begins the:", ["alert phase", "uncertainty phase", "distress phase", "urgency phase"], 0, "ALERFA."),
  Q("emergency-phases", "The three emergency phases, in order of increasing seriousness, are:", ["uncertainty, alert, distress", "alert, uncertainty, distress", "urgency, alert, distress", "uncertainty, urgency, distress"], 0, "INCERFA, ALERFA, DETRESFA."),

  Q("interception", "An intercepted aircraft should select transponder code:", ["7700", "7600", "7500", "7000"], 0, "SERA.11015: 7700 unless otherwise instructed."),
  Q("interception", "An intercepted aircraft should try to contact the intercepting aircraft on:", ["121.5 MHz", "123.45 MHz", "the last assigned frequency only", "135.48 MHz"], 0, "121.5 MHz."),
  Q("interception", "An intercepting aircraft rocks its wings, flashes its lights, then makes a slow level turn. This means:", ["you have been intercepted, follow me", "you may proceed", "land at this aerodrome", "you are entering a danger area"], 0, "Follow me."),
  Q("interception", "An intercepting aircraft makes an abrupt climbing turn of 90° or more without crossing your flight path. This means:", ["you may proceed", "follow me", "land at this aerodrome", "descend immediately"], 0, "Break-away = you may proceed."),

  Q("warning-signals", "A series of projectiles fired from the ground at 10-second intervals, each showing red and green lights or stars, means:", ["you are flying in, or about to enter, a restricted, prohibited or danger area", "the aerodrome below is closed and you must not land there", "you have been intercepted and must follow the signalling aircraft", "you must land at the nearest aerodrome as soon as possible"], 0, "Take remedial action — turn away."),
  Q("warning-signals", "The warning signal for an aircraft about to infringe a restricted area is fired at intervals of:", ["10 seconds", "5 seconds", "30 seconds", "60 seconds"], 0, "10-second intervals, red and green."),

  Q("sar-signals", "A ground-to-air signal 'V' laid out by survivors means:", ["require assistance", "require medical assistance", "no or negative", "proceeding in this direction"], 0, "V = assistance; X = medical."),
  Q("sar-signals", "A ground-to-air signal 'X' laid out by survivors means:", ["require medical assistance", "require assistance", "no or negative", "yes or affirmative"], 0, "X = medical."),
  Q("sar-signals", "A ground-to-air signal 'N' means:", ["no or negative", "yes or affirmative", "require assistance", "proceeding in this direction"], 0, "N = no; Y = yes."),
  Q("sar-signals", "A dropped supply container coloured blue contains:", ["food and water", "medical supplies", "blankets and clothing", "miscellaneous equipment"], 0, "Red medical, blue food/water, yellow blankets/clothing, black equipment."),
  Q("sar-signals", "By day, an aircraft acknowledges a ground signal by:", ["rocking its wings", "flashing its landing lights twice", "circling to the left", "lowering its landing gear"], 0, "Rocking wings by day; flashing lights twice at night."),

  Q("accident-investigation", "Accidents in the UK are investigated by the:", ["AAIB", "CAA", "police only", "aircraft insurer"], 0, "Air Accidents Investigation Branch."),
  Q("accident-investigation", "The main purpose of an AAIB investigation is to:", ["prevent future accidents", "apportion blame", "decide insurance claims", "prosecute the pilot"], 0, "Prevention, not blame."),
  Q("accident-investigation", "After an accident, the wreckage may be moved:", ["to rescue people, prevent fire or remove danger to the public", "once the pilot has photographed it from all sides", "by the aircraft owner at any time to protect it", "after 24 hours, if the AAIB has not arrived"], 0, "Otherwise, only with AAIB permission."),
  Q("accident-investigation", "An accident must be reported to the:", ["AAIB and the police, by the quickest means", "CAA within 72 hours, by post", "aircraft insurer within 7 days", "aerodrome operator only"], 0, "AAIB and police, quickest means. The 72-hour CAA rule is for MORs."),
  Q("accident-investigation", "For accident reporting, a 'serious injury' includes hospitalisation for more than:", ["48 hours, starting within 7 days of the injury", "24 hours, starting within 7 days of the injury", "48 hours, starting within 30 days of the injury", "72 hours, starting within 7 days of the injury"], 0, "More than 48 hours, commencing within 7 days."),
  Q("accident-investigation", "For accident reporting, an injury is classed as 'fatal' if death occurs within:", ["30 days", "7 days", "48 hours", "90 days"], 0, "Death within 30 days."),

  Q("occurrence-reporting", "A Mandatory Occurrence Report must be submitted to the CAA within:", ["72 hours", "24 hours", "7 days", "30 days"], 0, "72 hours of becoming aware."),
  Q("occurrence-reporting", "Confidential safety reports can be made to:", ["CHIRP", "the police", "the aircraft insurer", "Border Force"], 0, "CHIRP — the confidential reporting programme."),
  Q("occurrence-reporting", "The occurrence reporting system works under a:", ["just culture, focused on learning", "blame culture, focused on punishment", "no-reporting culture", "commercial-only culture"], 0, "Honest mistakes aren't punished; gross negligence isn't protected.")
