QUESTIONS.forEach((question, index) => {
  const sameTopicBefore = QUESTIONS.slice(0, index).filter(other => other.topicId === question.topicId).length;
  question.id = `${question.topicId}-${sameTopicBefore}`;
  question.topic = TOPICS.find(topic => topic.id === question.topicId).num;
});
